/* Inline the few LaTeX packages PaperTeX emits that are not in the engine's
   pre-bundled TeX Live subset, so an in-browser compile does not need a CTAN
   proxy for the default feature set.

   All are redistributable: booktabs (LPPL 1.3c), setspace (LPPL), soul and
   soul-ori (LPPL 1.3), ulem (free, see its own header). Their licence notices
   are inside the files and are preserved verbatim.

   Run:  node tools/bundle-texmf.js */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const src = path.join(root, 'engine', 'texmf');
const files = fs.readdirSync(src).filter((f) => f.endsWith('.sty')).sort();

let out = '/* PaperTeX — LaTeX packages inlined for the in-browser compiler.\n' +
  '   Generated by tools/bundle-texmf.js; do not edit by hand.\n' +
  '   Each file keeps its original licence notice. */\n' +
  '(function () {\n  window.PT = window.PT || {};\n  PT.texmf = {\n';

files.forEach(function (f, i) {
  const body = fs.readFileSync(path.join(src, f), 'utf8');
  out += '    ' + JSON.stringify(f) + ': ' + JSON.stringify(body) +
    (i < files.length - 1 ? ',' : '') + '\n';
});

out += '  };\n})();\n';
fs.writeFileSync(path.join(root, 'js', 'texmf.js'), out);

const kb = (fs.statSync(path.join(root, 'js', 'texmf.js')).size / 1024).toFixed(0);
console.log('js/texmf.js  ' + files.length + ' packages, ' + kb + ' kB');
console.log('  ' + files.join(', '));
